import csv
from collections import defaultdict

rows=list(csv.DictReader(open(CATALOG_CSV)))
zone_series=defaultdict(dict)
for r in rows:
    uri=r['point_uri'].split('#')[-1]
    zone,prop=uri.rsplit('.',1)
    zone_series[zone][prop]=r['timeseries_id']

target='2018-04-09T16:00:00'
tids={v for d in zone_series.values() for v in d.values()}
vals={}
for r in csv.DictReader(open(VALUES_CSV)):
    if r['timeseries_id'] in tids and r['timestamp']==target:
        vals[r['timeseries_id']]=float(r['value'])

best=None
for z,d in zone_series.items():
    if 'Zone_Air_Temperature_Sensor' in d and 'Zone_Air_Cooling_Temperature_Setpoint' in d:
        t=vals.get(d['Zone_Air_Temperature_Sensor'])
        s=vals.get(d['Zone_Air_Cooling_Temperature_Setpoint'])
        if t is not None and s is not None:
            diff=t-s
            if best is None or diff>best[1]:
                best=(z,diff,t,s)
for z,d in sorted(zone_series.items()):
    if 'Zone_Air_Temperature_Sensor' in d and 'Zone_Air_Cooling_Temperature_Setpoint' in d:
        print(z, vals.get(d['Zone_Air_Temperature_Sensor']), vals.get(d['Zone_Air_Cooling_Temperature_Setpoint']))
print("BEST",best)
